import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 1, the stamp (use it for a mistake): a red stamp slams onto a chat card and shakes it.
// Root.tsx: <Composition id="Stamp" component={Stamp} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', RED = '#E5484D';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

export const Stamp = ({text = 'WRONG', at = 0.9, ask = 'Help me write a breakup text...', reply = "Of course. Let's keep it kind and clear.", bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;                       // seconds
  // The hit: the stamp shrinks from 2.2x to its real size in a fifth of a second.
  const land = interpolate(t, [at, at + 0.2], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  // The shake: a fast wobble that dies away after the hit.
  const shake = t > at ? 2.6 * Math.exp(-(t - at) * 7) * Math.sin((t - at) * 46) : 0;
  const typed = reply.slice(0, Math.round(reply.length * interpolate(t, [0.1, at - 0.1], [0, 1], clamp)));
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 110, top: 560, width: 860, height: 500, padding: '56px 52px', ...CARD, transform: `rotate(${shake}deg)`}}>
        <div style={{display: 'flex', justifyContent: 'flex-end'}}>
          <div style={{background: '#EFECE5', borderRadius: 36, padding: '22px 34px', fontSize: 42, fontWeight: 600, letterSpacing: -0.8, whiteSpace: 'nowrap'}}>{ask}</div>
        </div>
        <div style={{marginTop: 64, fontSize: 46, fontWeight: 500, letterSpacing: -0.6, lineHeight: 1.25}}>{typed}</div>
      </div>
      {land > 0 ? (
        <div style={{position: 'absolute', left: 540, top: 810, transform: `translate(-50%, -50%) rotate(-7deg) scale(${2.2 - 1.2 * land})`, opacity: Math.min(1, land * 4),
          background: RED, color: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 14, boxShadow: `0 5px 0 ${INK}, 0 22px 30px rgba(40,32,18,0.22)`,
          padding: '6px 56px 14px', fontSize: 176, fontWeight: 900, letterSpacing: -4, lineHeight: 1.05, whiteSpace: 'nowrap'}}>
          {text}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 2, the switch (use it for a setting): a cursor glides in and flips a big switch off; a tick pops.
// Root.tsx: <Composition id="Switch" component={Switch} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E', GREY = '#A29D92';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const ease = (t, at, dur) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const lerp = (a, b, p) => a + (b - a) * p;

export const Switch = ({flipAt = 1.0, label = 'TRAIN ON MY CHATS', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const on = 1 - ease(t, flipAt, 0.22);                                       // 1 = on (knob right, green), 0 = off (knob left, grey)
  const glide = interpolate(t, [0.1, flipAt - 0.1], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const press = t > flipAt - 0.06 && t < flipAt + 0.1 ? 0.84 : 1;             // the cursor dips as it clicks
  const tick = ease(t, flipAt + 0.3, 0.2);
  const W = 680, H = 340, K = 270;
  const mix = [lerp(229, 0, on), lerp(225, 217, on), lerp(216, 126, on)].map(Math.round).join(',');   // grey #E5E1D8 -> green #00D97E
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 0, right: 0, top: 500, textAlign: 'center', fontFamily: MONO, fontWeight: 600, fontSize: 32, letterSpacing: 6, color: '#4B4740'}}>{label}</div>
      <div style={{position: 'absolute', left: 540 - W / 2, top: 590, width: W, height: H, borderRadius: H, background: `rgb(${mix})`, border: `2.5px solid ${INK}`,
        boxShadow: `0 5px 0 ${INK}, 0 26px 40px rgba(40,32,18,0.16)`, boxSizing: 'border-box'}}>
        <div style={{position: 'absolute', top: 32, left: lerp(33, W - K - 38, on), width: K, height: K, borderRadius: '50%', background: '#FFFFFF', border: `2.5px solid ${INK}`,
          boxShadow: '0 6px 12px rgba(40,32,18,0.18)', boxSizing: 'border-box'}} />
      </div>
      <div style={{position: 'absolute', left: 0, right: 0, top: 975, textAlign: 'center', fontSize: 150, fontWeight: 900, letterSpacing: -6, lineHeight: 1.1, color: on > 0.5 ? INK : GREY}}>
        {on > 0.5 ? 'On' : 'Off'}
      </div>
      {tick > 0 ? (
        <div style={{position: 'absolute', left: 868, top: 530, width: 104, height: 104, borderRadius: '50%', background: GREEN, border: `2.5px solid ${INK}`, boxSizing: 'border-box',
          display: 'grid', placeItems: 'center', transform: `scale(${lerp(1.7, 1, tick)})`, opacity: Math.min(1, tick * 4)}}>
          <svg width="56" height="56" viewBox="0 0 24 24"><path d="M4 12.8l5 5L20 6.6" fill="none" stroke={INK} strokeWidth="3.6" strokeLinecap="round" strokeLinejoin="round" /></svg>
        </div>
      ) : null}
      <svg width="68" height="85" viewBox="0 0 24 30" style={{position: 'absolute', left: lerp(900, 770, glide), top: lerp(1250, 826, glide), transform: `scale(${press})`,
        transformOrigin: '0 0', opacity: 1 - ease(t, flipAt + 0.45, 0.3), filter: 'drop-shadow(0 5px 6px rgba(40,32,18,0.3))'}}>
        <path d="M2 2 L2 24 L8 18.5 L12 27.5 L16 25.8 L12 17 L20 17 Z" fill="#FFFFFF" stroke={INK} strokeWidth="1.8" strokeLinejoin="round" />
      </svg>
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 3, the gauge (use it for a score): the needle sweeps from 0 to the score, the arc fills behind it and the number counts up.
// Root.tsx: <Composition id="Gauge" component={Gauge} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

export const Gauge = ({score = 7, max = 10, from = 0.35, dur = 0.9, label = 'YOUR ANSWER, OUT OF 10', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const v = score * interpolate(t, [from, from + dur], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const size = 700, r = size * 0.4, cx = size / 2, cy = size * 0.52, thick = size * 0.1;
  const point = (q) => [cx - r * Math.cos(Math.PI * q), cy - r * Math.sin(Math.PI * q)];   // q: 0 = far left, 1 = far right of the half circle
  const [x1, y1] = point(0), [x2, y2] = point(1), [xv, yv] = point(v / max);
  const arc = (x, y) => `M${x1} ${y1} A${r} ${r} 0 0 1 ${x} ${y}`;
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 110, top: 480, width: 860, height: 700, ...CARD}}>
        <svg width={size} height={size * 0.6} style={{position: 'absolute', left: 80, top: 62, overflow: 'visible'}}>
          <path d={arc(x2, y2)} fill="none" stroke={INK} strokeWidth={thick} strokeLinecap="round" />
          <path d={arc(x2, y2)} fill="none" stroke="#EFECE5" strokeWidth={thick - 5} strokeLinecap="round" />
          {v > 0.02 ? <path d={arc(xv, yv)} fill="none" stroke={GREEN} strokeWidth={thick - 5} strokeLinecap="round" /> : null}
          <line x1={cx} y1={cy} x2={cx + (xv - cx) * 0.76} y2={cy + (yv - cy) * 0.76} stroke={INK} strokeWidth={size * 0.024} strokeLinecap="round" />
          <circle cx={cx} cy={cy} r={size * 0.036} fill={INK} />
        </svg>
        <div style={{position: 'absolute', left: 0, right: 0, top: 440, textAlign: 'center', fontSize: 140, fontWeight: 900, letterSpacing: -5, lineHeight: 1}}>{Math.round(v)}/{max}</div>
        <div style={{position: 'absolute', left: 0, right: 0, top: 606, textAlign: 'center', fontFamily: MONO, fontSize: 24, fontWeight: 600, letterSpacing: 4, color: '#4B4740'}}>{label}</div>
      </div>
    </AbsoluteFill>
  );
};

