// Move 4, the chart that draws itself (use it for growth): the line draws from left to right while the big number counts up;
// a green badge pops when it finishes.
// Root.tsx: <Composition id="LiveChart" component={LiveChart} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

export const LiveChart = ({start = 1000, end = 1400, from = 0.2, dur = 1.15, badge = '+40%', title = 'Followers', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const p = interpolate(t, [from, from + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const pop = interpolate(t, [from + dur - 0.05, from + dur + 0.15], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const W = 760, H = 380;
  const points = [[0, 0.05], [0.14, 0.09], [0.3, 0.3], [0.5, 0.5], [0.72, 0.76], [1, 1]];   // the shape of the growth, as fractions of the box
  const path = points.map(([x, y], i) => `${i ? 'L' : 'M'}${(x * W).toFixed(1)} ${(H - y * H).toFixed(1)}`).join(' ');
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 110, top: 480, width: 860, height: 700, padding: '44px 50px', ...CARD}}>
        <div style={{fontFamily: MONO, fontSize: 22, fontWeight: 600, letterSpacing: 4, color: '#4B4740'}}>{title.toUpperCase()}</div>
        <div style={{display: 'flex', alignItems: 'center', gap: 24, marginTop: 4}}>
          <div style={{fontSize: 132, fontWeight: 900, letterSpacing: -5, lineHeight: 1.1}}>{Math.round(start + (end - start) * p).toLocaleString('en-GB')}</div>
          {pop > 0 ? (
            <div style={{background: GREEN, border: `2.5px solid ${INK}`, borderRadius: 12, boxShadow: `0 4px 0 ${INK}`, padding: '2px 22px 6px', fontSize: 66, fontWeight: 900,
              letterSpacing: -1.5, transform: `rotate(-4deg) scale(${1.7 - 0.7 * pop})`, opacity: Math.min(1, pop * 4)}}>{badge}</div>
          ) : null}
        </div>
        <svg width={W} height={H + 12} style={{marginTop: 34, overflow: 'visible'}}>
          <line x1="0" y1={H} x2={W} y2={H} stroke="#DAD5CA" strokeWidth="3" />
          {/* pathLength = 1 lets the dash offset run 1 -> 0, which draws the line from left to right */}
          <path d={path} pathLength="1" fill="none" stroke={INK} strokeWidth="7" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1" strokeDashoffset={1 - p} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 5, the heart monitor (use it for nerves): the line races in red at 138 beats a minute, then calms to 72 and turns green.
// Root.tsx: <Composition id="HeartMonitor" component={HeartMonitor} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E', RED = '#FF5A5F';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const lerp = (a, b, p) => a + (b - a) * p;
// One heartbeat as a function: a small bump, a dip, the spike, a dip, a soft bump, then flat. u runs 0 -> 1 across the beat.
const beat = (u) => (u < 0.1 ? 0.15 * Math.sin((u / 0.1) * Math.PI) : u < 0.16 ? -0.25 : u < 0.22 ? 1 : u < 0.28 ? -0.4 : u < 0.45 ? 0.2 * Math.sin(((u - 0.28) / 0.17) * Math.PI) : 0);

export const HeartMonitor = ({calmAt = 0.9, fast = 138, slow = 72, bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const calm = interpolate(t, [calmAt, calmAt + 0.5], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const W = 520, H = 320, color = calm > 0.5 ? GREEN : RED;
  const points = Array.from({length: 260}, (_, i) => {
    const x = i / 259;
    const phase = x * lerp(4.6, 2.2, calm) + t * lerp(2.3, 1.2, calm);            // more beats on screen and faster scrolling while the rate is high
    return `${(x * W).toFixed(1)},${(H / 2 - beat(((phase % 1) + 1) % 1) * lerp(110, 62, calm)).toFixed(1)}`;
  }).join(' ');
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT}}>
      <div style={{position: 'absolute', left: 110, top: 590, width: 860, height: 460, background: INK, borderRadius: 26, boxShadow: '0 30px 50px rgba(40,32,18,0.28)'}}>
        <svg width={W} height={H} style={{position: 'absolute', left: 44, top: 70}}>
          <polyline points={points} fill="none" stroke={color} strokeWidth="6" strokeLinejoin="round" strokeLinecap="round" />
        </svg>
        <div style={{position: 'absolute', right: 46, top: 120, textAlign: 'right', color}}>
          <div style={{fontSize: 168, fontWeight: 900, letterSpacing: -7, lineHeight: 1}}>{Math.round(lerp(fast, slow, calm))}</div>
          <div style={{fontFamily: MONO, fontSize: 28, fontWeight: 600, letterSpacing: 4, marginTop: 10}}>{calm > 0.5 ? 'BPM · CALM' : 'BPM'}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

