// Move 6, the bingo card (use it for cliches): three boxes in the top row tick green one by one, then a red BINGO stamp slams across.
// Root.tsx: <Composition id="BingoCard" component={BingoCard} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E', RED = '#E5484D';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const ease = (t, at, dur) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const WORDS = ['Hard worker', 'Team player', 'Passionate', 'Perfectionist', 'People person', 'Fast learner', 'Go-getter', 'Self-starter', 'Detail-oriented'];

export const BingoCard = ({ticks = [0.2, 0.55, 0.95], stampAt = 1.2, title = 'INTERVIEW BINGO', words = WORDS, bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const land = ease(t, stampAt, 0.2);
  const shake = t > stampAt ? 1.8 * Math.exp(-(t - stampAt) * 7) * Math.sin((t - stampAt) * 46) : 0;
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 110, top: 470, width: 860, height: 720, overflow: 'hidden', ...CARD, transform: `rotate(${shake}deg)`}}>
        <div style={{height: 82, borderBottom: `2.5px solid ${INK}`, display: 'grid', placeItems: 'center', fontFamily: MONO, fontSize: 28, fontWeight: 600, letterSpacing: 7}}>{title}</div>
        <div style={{display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 18, padding: 24, height: 720 - 82 - 6, boxSizing: 'border-box'}}>
          {words.map((word, i) => {
            const on = i < 3 ? ease(t, ticks[i], 0.16) : 0;                    // only the top row gets ticked
            return (
              <div key={i} style={{position: 'relative', display: 'grid', placeItems: 'center', textAlign: 'center', border: `2.5px solid ${INK}`, borderRadius: 14, fontSize: 31,
                fontWeight: 700, letterSpacing: -0.5, background: on > 0.5 ? GREEN : '#FFFFFF', transform: `scale(${1 + 0.07 * Math.sin(Math.PI * on)})`}}>
                {word}
              </div>
            );
          })}
        </div>
      </div>
      {land > 0 ? (
        <div style={{position: 'absolute', left: 540, top: 880, transform: `translate(-50%, -50%) rotate(-7deg) scale(${2.2 - 1.2 * land})`, opacity: Math.min(1, land * 4), background: RED,
          color: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 14, boxShadow: `0 5px 0 ${INK}, 0 22px 30px rgba(40,32,18,0.22)`, padding: '4px 54px 12px', fontSize: 160,
          fontWeight: 900, letterSpacing: -3, lineHeight: 1.05}}>BINGO</div>
      ) : null}
    </AbsoluteFill>
  );
};

