// Move 7, the magnifier (use it for the small print): a glass glides across a page of tiny text and the words under it grow big enough
// to read. The trick: the page is drawn twice. The second copy is 2.4x bigger and only shows through the round lens.
// Root.tsx: <Composition id="Magnifier" component={Magnifier} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

// The page of small print: grey bars for the lines nobody reads, and one real line in the middle.
const Sheet = ({line}) => (
  <div style={{width: 860, height: 600, padding: '56px 58px', boxSizing: 'border-box', fontFamily: FONT, color: INK}}>
    <div style={{fontFamily: MONO, fontSize: 24, fontWeight: 600, letterSpacing: 4, color: '#4B4740', marginBottom: 38}}>TERMS · PAGE 14 OF 31</div>
    {[0.92, 0.78, 0.84, null, 0.86, 0.6, 0.74].map((w, i) => w ? <div key={i} style={{height: 16, width: `${w * 100}%`, background: '#E4DFD5', borderRadius: 8, marginBottom: 30}} />
      : <div key={i} style={{fontSize: 27, fontWeight: 600, marginBottom: 28, whiteSpace: 'nowrap'}}><span style={{background: GREEN, borderRadius: 4, padding: '0 4px'}}>{line}</span></div>)}
    <div style={{height: 16, width: '70%', background: '#E4DFD5', borderRadius: 8}} />
  </div>
);

export const Magnifier = ({line = 'Reviewed chats can be kept for up to three years.', from = 0.25, dur = 1.35, zoom = 2.4, bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const p = interpolate(t, [from, from + dur], [0, 1], {...clamp, easing: Easing.inOut(Easing.cubic)});
  const X0 = 110, Y0 = 530, R = 178;                                           // the sheet's corner on screen, and the lens radius
  const cx = 262 + p * 500, cy = 792 + 10 * Math.sin(p * Math.PI);            // the lens centre: along the real line, with a slight arc
  return (
    <AbsoluteFill style={{background: bg}}>
      <div style={{position: 'absolute', left: X0, top: Y0, ...CARD, overflow: 'hidden'}}><Sheet line={line} /></div>
      {/* the lens: a round window onto a bigger copy of the same sheet, lined up so the point under the centre stays put */}
      <div style={{position: 'absolute', left: cx - R, top: cy - R, width: 2 * R, height: 2 * R, borderRadius: '50%', overflow: 'hidden', background: '#FFFFFF',
        border: `7px solid ${INK}`, boxSizing: 'border-box', boxShadow: '0 18px 30px rgba(40,32,18,0.25)'}}>
        <div style={{position: 'absolute', left: R - 7 - (cx - X0) * zoom, top: R - 7 - (cy - Y0) * zoom, transform: `scale(${zoom})`, transformOrigin: '0 0'}}><Sheet line={line} /></div>
      </div>
      <div style={{position: 'absolute', left: cx + R * 0.64, top: cy + R * 0.64, width: 170, height: 30, borderRadius: 15, background: INK, transform: 'rotate(45deg)', transformOrigin: '0 50%'}} />
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 8, the year roller (use it for deadlines): the number rolls upward like a slot machine from the first year to the last,
// blurred while it moves; a red stamp lands as it stops.
// Root.tsx: <Composition id="YearRoller" component={YearRoller} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', RED = '#E5484D';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif', MONO = '"IBM Plex Mono", ui-monospace, Menlo, monospace';
const CARD = {background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 18, boxShadow: `0 4px 0 ${INK}, 0 24px 44px rgba(40,32,18,0.13)`, boxSizing: 'border-box'};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};

export const YearRoller = ({years = [2026, 2027, 2028, 2029], from = 0.45, dur = 0.8, stamp = '3 years', label = 'KEPT UNTIL', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const roll = interpolate(t, [from, from + dur], [0, years.length - 1], {...clamp, easing: Easing.inOut(Easing.cubic)});   // which year is centred (1.5 = halfway)
  const speed = Math.abs(Math.sin(Math.PI * interpolate(t, [from, from + dur], [0, 1], clamp)));                           // 0 at rest, 1 mid-roll
  const land = interpolate(t, [from + dur - 0.2, from + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
  const ROW = 380;
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 110, top: 560, width: 860, height: 520, overflow: 'hidden', ...CARD}}>
        <div style={{position: 'absolute', left: 50, top: 38, fontFamily: MONO, fontSize: 26, fontWeight: 600, letterSpacing: 4, color: '#4B4740'}}>{label}</div>
        {/* the window the numbers roll through: one row tall, so only the year that is passing shows */}
        <div style={{position: 'absolute', left: 0, right: 0, top: 104, height: ROW, overflow: 'hidden'}}>
          <div style={{position: 'absolute', left: 0, right: 0, top: -roll * ROW, filter: `blur(${speed * 7}px)`}}>
            {years.map((y) => (
              <div key={y} style={{height: ROW, display: 'grid', placeItems: 'center', fontSize: 300, fontWeight: 900, letterSpacing: -13, lineHeight: 1}}>{y}</div>
            ))}
          </div>
        </div>
      </div>
      {land > 0 ? (
        <div style={{position: 'absolute', left: 800, top: 558, transform: `translate(-50%, -50%) rotate(7deg) scale(${2.2 - 1.2 * land})`, opacity: Math.min(1, land * 4), background: RED,
          color: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 12, boxShadow: `0 4px 0 ${INK}, 0 18px 26px rgba(40,32,18,0.2)`, padding: '2px 34px 10px', fontSize: 92,
          fontWeight: 900, letterSpacing: -2, whiteSpace: 'nowrap'}}>{stamp}</div>
      ) : null}
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 9, the wall of cards (use it for a crowd): cards pop in as a wave from the middle, then every card folds into one tile
// that shows the count.
// Root.tsx: <Composition id="CardWall" component={CardWall} durationInFrames={60} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif';
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const ease = (t, at, dur) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const lerp = (a, b, p) => a + (b - a) * p;
const LABELS = ['Is this mole normal?', 'Rewrite my CV', 'Reply to my boss', 'My payslip says...', 'Write a breakup text', 'Plan my budget',
  'My blood test results', 'Text to my ex', 'Help with my debt', 'My diary entry', 'Explain my contract', 'Fix my essay'];

export const CardWall = ({foldAt = 1.15, labels = LABELS, total = '12', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const cols = 3, rows = Math.ceil(labels.length / cols), cw = 270, ch = 148, gap = 22;
  const W = cols * cw + (cols - 1) * gap, H = rows * ch + (rows - 1) * gap;
  const fold = ease(t, foldAt, 0.35);                                        // 0 -> 1: the cards fly into the middle
  const tile = ease(t, foldAt + 0.05, 0.3);
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 540 - W / 2, top: 830 - H / 2, width: W, height: H}}>
        {labels.map((label, i) => {
          const cx = i % cols, cy = Math.floor(i / cols);
          const wave = Math.hypot(cx - (cols - 1) / 2, cy - (rows - 1) / 2);   // distance from the middle = this card's delay
          const pop = ease(t, 0.08 + wave * 0.07, 0.25);
          return (
            <div key={i} style={{position: 'absolute', left: lerp(cx * (cw + gap), W / 2 - cw / 2, fold), top: lerp(cy * (ch + gap), H / 2 - ch / 2, fold), width: cw, height: ch,
              background: '#FFFFFF', border: `2.5px solid ${INK}`, borderRadius: 14, boxShadow: `0 4px 0 ${INK}, 0 14px 22px rgba(40,32,18,0.10)`, boxSizing: 'border-box',
              display: 'grid', placeItems: 'center', textAlign: 'center', padding: 16, fontSize: 29, fontWeight: 700, letterSpacing: -0.5, lineHeight: 1.15,
              transform: `scale(${lerp(0.4, 1, pop) * (1 - 0.85 * fold)})`, opacity: Math.min(1, pop * 3) * (1 - fold)}}>
              {label}
            </div>
          );
        })}
        {tile > 0 ? (
          <div style={{position: 'absolute', left: W / 2 - 190, top: H / 2 - 190, width: 380, height: 380, borderRadius: 88, background: INK, color: '#FFFFFF', display: 'grid',
            placeItems: 'center', boxShadow: '0 36px 54px rgba(40,32,18,0.3)', transform: `scale(${lerp(0.5, 1, tile)})`, opacity: Math.min(1, tile * 3)}}>
            <div style={{textAlign: 'center'}}>
              <div style={{fontSize: 190, fontWeight: 900, letterSpacing: -8, lineHeight: 1, color: GREEN}}>{total}</div>
              <div style={{fontSize: 44, fontWeight: 700, marginTop: 4}}>chats</div>
            </div>
          </div>
        ) : null}
      </div>
    </AbsoluteFill>
  );
};

import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';

// Move 10, the phone that taps itself (use it for steps): three screens. On each one a row lights up green as if tapped and the next
// screen slides in; on the last screen the switch flips off and a tick pops.
// Root.tsx: <Composition id="PhoneTaps" component={PhoneTaps} durationInFrames={84} fps={30} width={1080} height={1920} />
const INK = '#161616', PAGE = '#F6F4EF', GREEN = '#00D97E';
const FONT = 'Inter, "Helvetica Neue", Arial, sans-serif';
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'};
const ease = (t, at, dur) => interpolate(t, [at, at + dur], [0, 1], {...clamp, easing: Easing.out(Easing.cubic)});
const SCREENS = [
  {title: 'Menu', rows: ['New chat', 'Search chats', 'Library', 'Settings'], tap: 3},
  {title: 'Settings', rows: ['Account', 'Notifications', 'Data controls', 'Security'], tap: 2},
];

export const PhoneTaps = ({step = 0.7, last = 'Improve the model for everyone', bg = PAGE}) => {
  const t = useCurrentFrame() / useVideoConfig().fps;
  const W = 500, H = 880, flipAt = 2 * step + 0.5;
  const off = ease(t, flipAt, 0.2), tick = ease(t, flipAt + 0.35, 0.2);
  return (
    <AbsoluteFill style={{background: bg, fontFamily: FONT, color: INK}}>
      <div style={{position: 'absolute', left: 540 - W / 2, top: 418, width: W, height: H, borderRadius: 70, background: INK, padding: 14, boxSizing: 'border-box',
        boxShadow: '0 36px 60px rgba(40,32,18,0.28)'}}>
        <div style={{position: 'relative', width: '100%', height: '100%', borderRadius: 54, background: '#FFFFFF', overflow: 'hidden'}}>
          <div style={{position: 'absolute', left: '50%', top: 14, width: 132, height: 32, borderRadius: 999, background: INK, transform: 'translateX(-50%)', zIndex: 5}} />
          {SCREENS.map((s, i) => {
            const enter = i === 0 ? 1 : ease(t, i * step, 0.25), leave = ease(t, (i + 1) * step, 0.25);    // each screen slides in from the right, out to the left
            const tapped = t > (i + 1) * step - 0.26;
            return (
              <div key={s.title} style={{position: 'absolute', inset: 0, padding: '84px 30px', boxSizing: 'border-box', background: '#FFFFFF',
                transform: `translateX(${(1 - enter) * 100 - leave * 100}%)`}}>
                <div style={{fontSize: 46, fontWeight: 900, letterSpacing: -1.5, marginBottom: 22}}>{s.title}</div>
                {s.rows.map((row, k) => (
                  <div key={row} style={{fontSize: 31, fontWeight: 700, letterSpacing: -0.5, padding: '18px 18px', marginBottom: 8, borderRadius: 14,
                    background: tapped && k === s.tap ? GREEN : 'transparent', border: `2.5px solid ${tapped && k === s.tap ? INK : 'transparent'}`,
                    transform: `scale(${tapped && k === s.tap ? 1.03 : 1})`}}>{row}</div>
                ))}
              </div>
            );
          })}
          <div style={{position: 'absolute', inset: 0, padding: '84px 30px', boxSizing: 'border-box', background: '#FFFFFF', transform: `translateX(${(1 - ease(t, 2 * step, 0.25)) * 100}%)`}}>
            <div style={{fontSize: 46, fontWeight: 900, letterSpacing: -1.5, marginBottom: 30}}>Data controls</div>
            <div style={{display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 18}}>
              <div style={{fontSize: 31, fontWeight: 800, letterSpacing: -0.5, lineHeight: 1.15}}>{last}</div>
              <div style={{flex: 'none', width: 116, height: 66, borderRadius: 66, border: `2.5px solid ${INK}`, background: off > 0.5 ? '#E5E1D8' : GREEN, position: 'relative', boxSizing: 'border-box'}}>
                <div style={{position: 'absolute', top: 6, left: 6 + (1 - off) * 50, width: 49, height: 49, borderRadius: '50%', background: '#FFFFFF', border: `2.5px solid ${INK}`, boxSizing: 'border-box'}} />
              </div>
            </div>
            {tick > 0 ? (
              <div style={{margin: '80px auto 0', width: 150, height: 150, borderRadius: '50%', background: GREEN, border: `2.5px solid ${INK}`, boxSizing: 'border-box', display: 'grid',
                placeItems: 'center', transform: `scale(${1.7 - 0.7 * tick})`, opacity: Math.min(1, tick * 4)}}>
                <svg width="82" height="82" viewBox="0 0 24 24"><path d="M4 12.8l5 5L20 6.6" fill="none" stroke={INK} strokeWidth="3.4" strokeLinecap="round" strokeLinejoin="round" /></svg>
              </div>
            ) : null}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};
